import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Pages in AL: Overview and Creating Our First Page","description":"","frontmatter":{},"headers":[],"relativePath":"tables-fields-and-business-data/pages-overview.md","filePath":"tables-fields-and-business-data/pages-overview.md"}`),a={name:`tables-fields-and-business-data/pages-overview.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="pages-in-al-overview-and-creating-our-first-page" tabindex="-1">Pages in AL: Overview and Creating Our First Page <a class="header-anchor" href="#pages-in-al-overview-and-creating-our-first-page" aria-label="Permalink to “Pages in AL: Overview and Creating Our First Page”">​</a></h1><p>A <strong>page</strong> is the user interface through which people view and interact with data in Business Central. Pages can display records, accept user input, and provide actions for performing business tasks. <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-pages-overview?trk=article-ssr-frontend-pulse_little-text-block" target="_blank" rel="noreferrer">Microsoft Learn</a></p><p>We&#39;ve already created our <code>Course</code> table. Now let&#39;s create a page that displays its data.</p><h2 id="common-page-types" tabindex="-1">Common page types <a class="header-anchor" href="#common-page-types" aria-label="Permalink to “Common page types”">​</a></h2><p>Business Central has several page types, each designed for a particular purpose.</p><table tabindex="0"><thead><tr><th>Page type</th><th>Purpose</th><th>Example</th></tr></thead><tbody><tr><td><code>List</code></td><td>Displays multiple records in rows.</td><td>A list of training courses</td></tr><tr><td><code>Card</code></td><td>Displays and edits one record at a time.</td><td>Details of a particular course</td></tr><tr><td><code>Document</code></td><td>Presents a business document, often combining a header and lines.</td><td>A sales order</td></tr><tr><td><code>RoleCenter</code></td><td>Provides a user&#39;s main workspace.</td><td>A sales manager&#39;s home page</td></tr><tr><td><code>ListPart</code></td><td>Displays a list within another page.</td><td>Related records in a FactBox</td></tr><tr><td><code>StandardDialog</code></td><td>Collects user input for a task.</td><td>A dialog asking for parameters</td></tr></tbody></table><p>For now, we&#39;ll focus on <strong>List</strong> and <strong>Card</strong> pages. These will be sufficient for our course catalogue. <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-pages-overview?trk=article-ssr-frontend-pulse_little-text-block" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h2 id="how-do-we-create-a-page" tabindex="-1">How do we create a page? <a class="header-anchor" href="#how-do-we-create-a-page" aria-label="Permalink to “How do we create a page?”">​</a></h2><p>Let&#39;s create a List page for our <code>Course</code> table.</p><p>In VS Code, create a new file named <code>CourseList.Page.al</code>.</p><p>Add the following code:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace LearningAl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>page 50103 &quot;Course List&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = List;</span></span>
<span class="line"><span>    SourceTable = Course;</span></span>
<span class="line"><span>    Caption = &#39;Course List&#39;;</span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span>    UsageCategory = Lists;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    layout</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        area(Content)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            repeater(General)</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                field(&quot;Course Code&quot;; Rec.&quot;Course Code&quot;)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(&quot;Course Name&quot;; Rec.&quot;Course Name&quot;)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(Description; Rec.Description)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(Price; Rec.Price)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Let&#39;s understand the important parts without getting too deep into page development yet.</p><h3 id="a-declaring-the-page" tabindex="-1">A. Declaring the page <a class="header-anchor" href="#a-declaring-the-page" aria-label="Permalink to “A. Declaring the page”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50103 &quot;Course List&quot;</span></span></code></pre></div><p>This declares a page object with ID <code>50103</code> and the name <code>Course List</code>.</p><p>Like tables, pages have object IDs. Make sure the ID is available in your project&#39;s permitted range.</p><h3 id="b-connecting-the-page-to-our-table" tabindex="-1">B. Connecting the page to our table <a class="header-anchor" href="#b-connecting-the-page-to-our-table" aria-label="Permalink to “B. Connecting the page to our table”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PageType = List;</span></span>
<span class="line"><span>SourceTable = Course;</span></span></code></pre></div><p>These two properties are particularly important.</p><ul><li><code>PageType = List</code> tells Business Central to display records in a list.</li><li><code>SourceTable = Course</code> tells Business Central that the page works with records from our <code>Course</code> table.</li></ul><p><strong>The page doesn&#39;t store the course data itself.</strong> It displays and interacts with records stored in the table.</p><h3 id="c-defining-the-layout" tabindex="-1">C. Defining the layout <a class="header-anchor" href="#c-defining-the-layout" aria-label="Permalink to “C. Defining the layout”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>layout</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    area(Content)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        repeater(General)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            // Fields go here</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The <code>layout</code> section defines the page&#39;s visual structure.</p><ul><li><code>area(Content)</code> defines the main content area.</li><li><code>repeater(General)</code> defines a group of controls that repeats for each record in the list.</li></ul><p>Because this is a List page, each course will appear as a row.</p><h3 id="d-displaying-table-fields" tabindex="-1">D. Displaying table fields <a class="header-anchor" href="#d-displaying-table-fields" aria-label="Permalink to “D. Displaying table fields”">​</a></h3><p>Consider this control:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(&quot;Course Name&quot;; Rec.&quot;Course Name&quot;)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>It tells Business Central to display the <code>Course Name</code> field from the current record.</p><p><code>Rec</code> is the page&#39;s record variable. Since our source table is <code>Course</code>, <code>Rec</code> represents a course record.</p><p>We&#39;ve included four fields in our page, so those fields will appear as columns in the list.</p><p>The other two properties are:</p><ul><li><code>Caption = &#39;Course List&#39;</code>: Provides the page&#39;s display title.</li><li><code>UsageCategory = Lists</code>: Categorizes the page for discovery through Business Central&#39;s navigation and Tell Me search.</li></ul><p>These properties help make the page accessible to users. <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-page-object" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h2 id="publish-and-view-the-page-in-business-central" tabindex="-1">Publish and view the page in Business Central <a class="header-anchor" href="#publish-and-view-the-page-in-business-central" aria-label="Permalink to “Publish and view the page in Business Central”">​</a></h2><p>Let&#39;s see our work!</p><p><strong>Step 1:</strong> Save <code>CourseList.Page.al</code>.</p><p><strong>Step 2:</strong> Press <strong>F5</strong> in VS Code to publish your extension.</p><p><strong>Step 3:</strong> Wait for publishing to complete successfully.</p><p><strong>Step 4:</strong> Open Business Central in your browser.</p><p><strong>Step 5:</strong> Press <code>Alt+Q</code> to open Tell Me, then search for <strong>Course List</strong>.</p><p><strong>Step 6:</strong> Open the page.</p><p>You should see a list with these columns:</p><table tabindex="0"><thead><tr><th>Course Code</th><th>Course Name</th><th>Description</th><th style="text-align:right;">Price</th></tr></thead><tbody><tr><td></td><td></td><td></td><td style="text-align:right;"></td></tr></tbody></table><p>If there are no records in the table yet, the list will be empty. That&#39;s expected.</p><h3 id="add-some-sample-records" tabindex="-1">Add some sample records <a class="header-anchor" href="#add-some-sample-records" aria-label="Permalink to “Add some sample records”">​</a></h3><p>If the page allows editing, create a few courses:</p><table tabindex="0"><thead><tr><th>Course Code</th><th>Course Name</th><th>Description</th><th style="text-align:right;">Price</th></tr></thead><tbody><tr><td>CS101</td><td>Introduction to Programming</td><td>Learn programming fundamentals</td><td style="text-align:right;">1500</td></tr><tr><td>CS102</td><td>Database Fundamentals</td><td>Learn relational databases</td><td style="text-align:right;">2000</td></tr><tr><td>CS103</td><td>Web Development</td><td>Build web applications</td><td style="text-align:right;">2500</td></tr></tbody></table><p>Save each record by completing the row and moving out of it.</p><p>If editing is unavailable, check the page&#39;s editability and your permissions.</p><p>Once saved, the records should appear in your list.</p><p><strong>Congratulations!</strong> You&#39;ve created a table, connected a page to it, and displayed your business data in Business Central.</p><h2 id="what-we-ve-learned" tabindex="-1">What we&#39;ve learned <a class="header-anchor" href="#what-we-ve-learned" aria-label="Permalink to “What we&#39;ve learned”">​</a></h2><p>The relationship between our objects is now:</p><p><strong><code>Course</code> table → <code>Course List</code> page → Business Central interface</strong></p><p>The table defines the structure and stores the data. The page presents that data to users.</p><p>We&#39;ll keep this page throughout the rest of the tables module. Whenever we introduce a new field or data-related concept, we can update the page to see the results.</p><h3 id="official-documentation" tabindex="-1">Official documentation <a class="header-anchor" href="#official-documentation" aria-label="Permalink to “Official documentation”">​</a></h3><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-pages-overview?trk=article-ssr-frontend-pulse_little-text-block" target="_blank" rel="noreferrer">Microsoft Learn: Pages overview</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-page-object" target="_blank" rel="noreferrer">Microsoft Learn: Page object</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-page-types-and-layouts" target="_blank" rel="noreferrer">Microsoft Learn: Page types and layouts</a></li></ul>`,61)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};